updateTimeline: function (currentTime, duration, bufferedEnd) {
  if (!this._dom.currentTime) this._cacheDom();
  var d = this._dom;

  var cur = Math.max(0, currentTime || 0);
  var dur = Math.max(0, duration || 0);
  var remaining = Math.max(0, dur - cur);

  if (d.currentTime) d.currentTime.textContent = formatTime(cur);
  if (d.durationTime) {
