args.ReplacementContent:
.osd-progress-wrapper {
  display: flex;
  align-items: center;
  gap: 20px;
  width: 100%;
  padding: 0 4px;
}

.osd-time {
  font-family: var(--cinema-font-family, "Google Sans", Roboto, sans-serif);
  font-size: 20px;
  font-weight: var(--font-weight-medium, 500);
  color: var(--cinema-text-primary, #e8eaed);
  font-variant-numeric: tabular-nums;
  min-width: 88px;
  text-align: center;
  letter-spacing: 0.4px;
  user-select: none;
}

#osd-duration-time {
  color: var(--cinema-text-secondary, #bdc1c6);
}

.osd-progress-track {
  flex: 1;
  height: 8px;
  background-color: rgba(255, 255, 255, 0.16);
  border-radius: var(--radius-pill);
  position: relative;
  outline: none;
  cursor: pointer;
  transition: height 0.22s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              box-shadow 0.22s ease,
              background-color 0.22s ease;
}

/* Spatial Focus State on Scrub Bar */
.osd-progress-track:focus,
.osd-progress-track.focused,
.osd-progress-track[data-nav="true"].focused {
  height: 12px;
  background-color: rgba(255, 255, 255, 0.26);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.25), 0 0 20px rgba(149, 255, 80, 0.65);
}

/* Buffered Range Indicator (Network Cache Ahead) */
.osd-buffer-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 0%;
  background-color: rgba(232, 234, 237, 0.35);
  border-radius: var(--radius-pill);
  transition: width 0.25s linear;
  pointer-events: none;
}

/* Elapsed Stream Progress Fill */
.osd-progress-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #7CD43B 0%, var(--color-accent-primary, #95FF50) 100%);
  border-radius: var(--radius-pill);
  box-shadow: 0 0 12px rgba(149, 255, 80, 0.55);
  pointer-events: none;
}

/* Visual Scrub Thumb */
.osd-scrub-thumb {
  position: absolute;
  top: 50%;
  left: 0%;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background-color: #FFFFFF;
  border: 2px solid var(--color-accent-primary, #95FF50);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.6), 0 0 12px rgba(149, 255, 80, 0.5);
  transform: translate(-50%, -50%);
  transition: transform 0.2s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              width 0.2s ease,
              height 0.2s ease,
              box-shadow 0.2s ease;
  pointer-events: none;
}

/* Focused Thumb Expansion */
.osd-progress-track:focus .osd-scrub-thumb,
.osd-progress-track.focused .osd-scrub-thumb,
.osd-progress-track[data-nav="true"].focused .osd-scrub-thumb {
  width: 24px;
  height: 24px;
  border-width: 3px;
  background-color: #FFFFFF;
  box-shadow: 0 0 0 5px #FFFFFF, 0 0 24px rgba(149, 255, 80, 0.85);
  transform: translate(-50%, -50%) scale(1.12);
}

/* ==========================================================================
   Action Controls Row
   ========================================================================== */
.osd-controls-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 72px;
}

.osd-controls-main {
  display: flex;
  align-items: center;
  gap: 24px;
}

.osd-controls-aux {
  display: flex;
  align-items: center;
  gap: 16px;
}

.osd-btn,
.pill.osd-btn {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background-color: rgba(60, 64, 67, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: var(--cinema-text-primary, #e8eaed);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  outline: none;
  position: relative;
  transition: transform 0.2s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              background-color 0.2s ease,
              box-shadow 0.2s ease,
              border-color 0.2s ease;
}

.osd-btn .btn-subscript {
  position: absolute;
  bottom: 8px;
  font-size: 10px;
  font-weight: var(--font-weight-bold, 700);
  color: var(--cinema-text-primary, #e8eaed);
  line-height: 1;
}

.osd-btn.btn-play-pause {
  width: 68px;
  height: 68px;
  background-color: var(--color-accent-primary, #95FF50);
  color: #04120B;
  border: none;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4);
}

.osd-btn.btn-play-pause svg {
  width: 32px;
  height: 32px;
  fill: #04120B;
}

.osd-pill-btn,
.pill.osd-pill-btn {
  width: auto;
  height: 52px;
  padding: 0 24px;
  border-radius: var(--radius-pill, 28px);
  background-color: rgba(60, 64, 67, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: var(--cinema-text-primary, #e8eaed);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--cinema-font-family, "Google Sans", Roboto, sans-serif);
  font-size: var(--font-size-body, 18px);
  font-weight: var(--font-weight-medium, 500);
  cursor: pointer;
  outline: none;
  transition: transform 0.2s var(--cinema-ease-decel, cubic-bezier(0.2, 0.8, 0.2, 1)),
              background-color 0.2s ease,
              box-shadow 0.2s ease,
              border-color 0.2s ease;
}

/* ==========================================================================
   Focus State Indicators (10-Foot Spatial Remote Navigation)
   ========================================================================== */
.osd-btn[data-nav="true"].focused,
.osd-btn.focused,
.osd-pill-btn[data-nav="true"].focused,
.osd-pill-btn.focused,
.pill[data-nav="true"].focused,
.pill.focused {
  background-color: #FFFFFF !important;
  color: #202124 !important;
  border-color: #FFFFFF !important;
  transform: scale(1.08) !important;
  box-shadow: 0 0 0 5px #FFFFFF, 0 0 28px rgba(149, 255, 80, 0.65) !important;
  z-index: 10;
}

.osd-btn[data-nav="true"].focused svg:not(#osd-play-icon),
.osd-btn.focused svg:not(#osd-play-icon),
.osd-pill-btn[data-nav="true"].focused svg,
.osd-pill-btn.focused svg {
  color: #202124 !important;
  stroke: #202124 !important;
  fill: none !important;
}

.osd-btn.focused .btn-subscript,
.osd-pill-btn.focused #osd-subtitles-label,
.osd-pill-btn.focused #osd-server-label {
  color: #202124 !important;
  font-weight: 600 !important;
}

.osd-btn.btn-play-pause[data-nav="true"].focused,
.osd-btn.btn-play-pause.focused {
  background-color: #B4FF78 !important;
  border: 2px solid #FFFFFF !important;
  box-shadow: 0 0 0 5px #FFFFFF, 0 0 36px rgba(149, 255, 80, 0.95) !important;
  transform: scale(1.10) !important;
  z-index: 10;
}

.osd-btn.btn-play-pause[data-nav="true"].focused svg,
.osd-btn.btn-play-pause.focused svg {
  fill: #04120B !important;
  stroke: none !important;
}

/* ==========================================================================
   Buffering Spinner Overlay (GPU Accelerated, No Backdrop Filter)
   ========================================================================== */
.player-buffering-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  z-index: 208;
  background-color: rgba(14, 16, 20, 0.78);
  transform: translateZ(0);
  will-change: opacity;
  pointer-events: none;
}

.buffering-spinner {
  width: 68px;
  height: 68px;
  border: 4px solid rgba(232, 234, 237, 0.15);
  border-top-color: var(--color-accent-primary, #95FF50);
  border-right-color: rgba(149, 255, 80, 0.4);
  border-radius: 50%;
  animation: playerSpin 0.85s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  will-change: transform;
  transform: translateZ(0);
  box-shadow: 0 0 20px rgba(149, 255, 80, 0.25);
}

.buffering-text {
  font-family: var(--cinema-font-family, "Google Sans", sans-serif);
  font-size: 22px;
